"use client";

import { useState } from "react";
import CardList from "../_components/cardList";

export default function Admin() {
    const [password, setPassword] = useState("");
    const [accessGranted, setAccessGranted] = useState(false);
    const [experiences, setExperiences] = useState<ExperienceType[]>([]);
    const [editingExp, setEditingExp] = useState<ExperienceType | null>(null);



  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    const res = await fetch("/api/admin", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ password }),
    });
    const data = await res.json();

    if (data.success) {
        setAccessGranted(true);
    } else {
        alert("wrong password");
    }
  }

  // Fetch experiences
  async function fetchExperiences() {
    const res = await fetch("/api/admin/experience");
    const data = await res.json();
    setExperiences(data);
  }

  // Add or update experience
  async function saveExperience(exp: ExperienceType) {
    const method = exp._id ? "PUT" : "POST";

    await fetch("/api/admin/experience", {
      method,
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(exp),
    });
    fetchExperiences();
    setEditingExp(null);
  }

  // Delete experience
  async function deleteExperience(id: string) {
    await fetch("/api/experiences", {
      method: "DELETE",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id }),
    });
    fetchExperiences();
  }

  if (accessGranted) {
    return (
        <div className="flex justify-center flex-col items-center h-screen">
        <h1>Admin Interface</h1>
        <h2>Experiences</h2>
        <button onClick={fetchExperiences}>Add New</button>
        <section id="cas" className="relative snap-start h-screen w-screen flex justify-center items-center">
            <CardList />
        </section>
        <ul>
            {experiences.map((exp) => (
            <li key={exp._id}>
                <strong>{exp.title}</strong>
                <button onClick={() => setEditingExp(exp)}>Edit</button>
                <button onClick={() => deleteExperience(exp._id)}>Delete</button>
            </li>
            ))}
        </ul>

        {editingExp && (
            <form
            onSubmit={(e) => {
                e.preventDefault();
                saveExperience(editingExp);
            }}
            >
            <input
                type="text"
                placeholder="Title"
                value={editingExp.title || ""}
                onChange={(e) =>
                setEditingExp({ ...editingExp, title: e.target.value })
                }
            />
            <textarea
                placeholder="Description"
                value={editingExp.description || ""}
                onChange={(e) =>
                setEditingExp({ ...editingExp, description: e.target.value })
                }
            />
            <textarea
                placeholder="Tips"
                value={editingExp.tips || ""}
                onChange={(e) =>
                setEditingExp({ ...editingExp, tips: e.target.value })
                }
            />
            {/* You can expand this with strands, members, hashtags, images, etc. */}
            <button type="submit">Save</button>
            <button type="button" onClick={() => setEditingExp(null)}>
                Cancel
            </button>
            </form>
        )}
        </div>
    );
    }

  return (
    <div className="flex justify-center items-center h-screen">
        <form className="flex justify-center items-center bubble rounded-full h-[5vh] px-5" onSubmit={handleSubmit}>
            <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Enter password"
            />
            <button type="submit">Submit</button>
        </form>
    </div>
  );
}
